import{_ as o,a0 as p,w as d,s as r,ao as n,I as t,x as s,a1 as a,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const v=JSON.parse('{"title":"如何在 Linux 中實時監控日誌文件 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 中實時監控日誌文件 | LCTT (202108) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 中實時監控日誌文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 中實時監控日誌文件 | LCTT (202108) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202108/20210822 How to Monitor Log Files in Real Time in Linux -Desktop and Server","title":"如何在 Linux 中實時監控日誌文件","tag":"202108","desc":""},"relativePath":"202108/20210822 How to Monitor Log Files in Real Time in Linux -Desktop and Server.md","filePath":"[post].md"}'),u={name:"202108/20210822 How to Monitor Log Files in Real Time in Linux -Desktop and Server.md"};function g(h,i,k,b,m,f){const l=p("Link");return d(),r("div",null,[i[25]||(i[25]=n(`<h1 id="如何在-linux-中實時監控日誌文件" tabindex="-1">如何在 Linux 中實時監控日誌文件 <a class="header-anchor" href="#如何在-linux-中實時監控日誌文件" aria-label="Permalink to “如何在 Linux 中實時監控日誌文件”">​</a></h1><blockquote><p>本教程解釋瞭如何實時監控 Linux 日誌文件（桌面、服務器或應用），以進行診斷和故障排除。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202108/30/082607bmf6nlud6sdy49rm.jpg" alt=""></p><p>當你在你的 Linux 桌面、服務器或任何應用中遇到問題時，你會首先查看各自的日誌文件。日誌文件通常是來自應用的文本和信息流，上面有一個時間戳。它可以幫助你縮小具體的實例，並幫助你找到任何問題的原因。它也可以幫助從網絡上獲得援助。</p><p>一般來説，所有的日誌文件都位於 <code>/var/log</code> 中。這個目錄包含以 <code>.log</code> 為擴展名的特定應用、服務的日誌文件，它還包含單獨的其他目錄，這些目錄包含其日誌文件。</p><p><img src="https://www.debugpoint.com/blog/wp-content/uploads/2021/08/log-files-in-var-log-1024x312.jpeg" alt="log files in var-log"></p><p>所以説，如果你想監控一堆日誌文件或特定的日誌文件。這裏有一些你可以做到方法。</p><h3 id="實時監控-linux-日誌文件" tabindex="-1">實時監控 Linux 日誌文件 <a class="header-anchor" href="#實時監控-linux-日誌文件" aria-label="Permalink to “實時監控 Linux 日誌文件”">​</a></h3><h4 id="使用-tail-命令" tabindex="-1">使用 tail 命令 <a class="header-anchor" href="#使用-tail-命令" aria-label="Permalink to “使用 tail 命令”">​</a></h4><p>使用 <code>tail</code> 命令是實時跟蹤日誌文件的最基本方法。特別是，如果你所在的服務器只有一個終端，沒有 GUI。這是很有幫助的。</p><p>比如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>tail /path/to/log/file</span></span></code></pre></div><p><img src="https://www.debugpoint.com/blog/wp-content/uploads/2021/08/Monitoring-multiple-log-files-via-tail-1024x444.jpeg" alt="Monitoring multiple log files via tail"></p><p>使用開關 <code>-f</code> 來跟蹤日誌文件，它是實時更新的。例如，如果你想跟蹤 <code>syslog</code>，你可以使用以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>tail -f /var/log/syslog</span></span></code></pre></div><p>你可以用一個命令監控多個日誌文件，使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>tail -f /var/log/syslog /var/log/dmesg</span></span></code></pre></div><p>如果你想監控 http 或 sftp 或任何服務器，你也可以在這個命令中監控它們各自的日誌文件。</p><p>記住，上述命令需要管理員權限。</p><h4 id="使用-lnav-日誌文件瀏覽器" tabindex="-1">使用 lnav（日誌文件瀏覽器） <a class="header-anchor" href="#使用-lnav-日誌文件瀏覽器" aria-label="Permalink to “使用 lnav（日誌文件瀏覽器）”">​</a></h4><p><img src="https://www.debugpoint.com/blog/wp-content/uploads/2021/08/lnav-Running-1024x447.jpeg" alt="lnav Running"></p><p><code>lnav</code> 是一個很好的工具，你可以用它來通過彩色編碼的信息以更有條理的方式監控日誌文件。在 Linux 系統中，它不是默認安裝的。你可以用下面的命令來安裝它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install lnav ### Ubuntu</span></span>
<span class="line"><span>sudo dnf install lnav ### Fedora</span></span></code></pre></div>`,23)),t("p",null,[i[1]||(i[1]=s("好的是，如果你不想安裝它，你可以直接下載其預編譯的可執行文件，然後在任何地方運行。甚至從 U 盤上也可以。它不需要設置，而且有很多功能。使用 ",-1)),i[2]||(i[2]=t("code",null,"lnav",-1)),i[3]||(i[3]=s("，你可以通過 SQL 查詢日誌文件，以及其他很酷的功能，你可以在它的 ",-1)),a(l,{href:"https://lnav.org/features"},{default:e(()=>[...i[0]||(i[0]=[s("官方網站",-1)])]),_:1}),i[4]||(i[4]=s(" 上了解。",-1))]),i[26]||(i[26]=n(`<p>一旦安裝，你可以簡單地用管理員權限從終端運行 <code>lnav</code>，它將默認顯示 <code>/var/log</code> 中的所有日誌並開始實時監控。</p><h4 id="關於-systemd-的-journalctl-説明" tabindex="-1">關於 systemd 的 journalctl 説明 <a class="header-anchor" href="#關於-systemd-的-journalctl-説明" aria-label="Permalink to “關於 systemd 的 journalctl 説明”">​</a></h4><p>今天所有的現代 Linux 發行版大多使用 systemd。systemd 提供了運行 Linux 操作系統的基本框架和組件。systemd 通過 <code>journalctl</code> 提供日誌服務，幫助管理所有 systemd 服務的日誌。你還可以通過以下命令實時監控各個 systemd 服務和日誌。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>journalctl -f</span></span></code></pre></div><p>下面是一些具體的 <code>journalctl</code> 命令，可以在一些情況下使用。你可以將這些命令與上面的 <code>-f</code> 開關結合起來，開始實時監控。</p><ul><li>對緊急系統信息，使用：<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>journalctl -p 0</span></span></code></pre></div></li><li>顯示帶有解釋的錯誤：<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>journalctl -xb -p 3</span></span></code></pre></div></li><li>使用時間控制來過濾輸出：<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>journalctl --since &quot;2020-12-04 06:00:00&quot;</span></span>
<span class="line"><span>journalctl --since &quot;2020-12-03&quot; --until &quot;2020-12-05 03:00:00&quot;</span></span>
<span class="line"><span>journalctl --since yesterday</span></span>
<span class="line"><span>journalctl --since 09:00 --until &quot;1 hour ago&quot;</span></span></code></pre></div></li></ul>`,6)),t("p",null,[i[6]||(i[6]=s("如果你想了解更多關於 ",-1)),i[7]||(i[7]=t("code",null,"journalctl",-1)),i[8]||(i[8]=s(" 的細節，我已經寫了一個 ",-1)),a(l,{href:"https://www.debugpoint.com/2020/12/systemd-journalctl/"},{default:e(()=>[...i[5]||(i[5]=[s("指南",-1)])]),_:1}),i[9]||(i[9]=s("。",-1))]),i[27]||(i[27]=t("h3",{id:"結束語",tabindex:"-1"},[s("結束語 "),t("a",{class:"header-anchor",href:"#結束語","aria-label":"Permalink to “結束語”"},"​")],-1)),i[28]||(i[28]=t("p",null,"我希望這些命令和技巧能幫助你找出桌面或服務器問題/錯誤的根本原因。對於更多的細節，你可以隨時參考手冊，擺弄各種開關。如果你對這篇文章有什麼意見或看法，請在下面的評論欄告訴我。",-1)),i[29]||(i[29]=t("p",null,"加油。",-1)),i[30]||(i[30]=t("hr",null,null,-1)),t("p",null,[i[11]||(i[11]=s("via: ",-1)),a(l,{href:"https://www.debugpoint.com/2021/08/monitor-log-files-real-time/"},{default:e(()=>[...i[10]||(i[10]=[s("https://www.debugpoint.com/2021/08/monitor-log-files-real-time/",-1)])]),_:1})]),t("p",null,[i[16]||(i[16]=s("作者：",-1)),a(l,{href:"https://www.debugpoint.com/author/admin1/"},{default:e(()=>[...i[12]||(i[12]=[s("Arindam",-1)])]),_:1}),i[17]||(i[17]=s(" 選題：",-1)),a(l,{href:"https://github.com/lujun9972"},{default:e(()=>[...i[13]||(i[13]=[s("lujun9972",-1)])]),_:1}),i[18]||(i[18]=s(" 譯者：",-1)),a(l,{href:"https://github.com/geekpi"},{default:e(()=>[...i[14]||(i[14]=[s("geekpi",-1)])]),_:1}),i[19]||(i[19]=s(" 校對：",-1)),a(l,{href:"https://github.com/wxy"},{default:e(()=>[...i[15]||(i[15]=[s("wxy",-1)])]),_:1})]),t("p",null,[i[22]||(i[22]=s("本文由 ",-1)),a(l,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...i[20]||(i[20]=[s("LCTT",-1)])]),_:1}),i[23]||(i[23]=s(" 原創編譯，",-1)),a(l,{href:"https://linux.cn/"},{default:e(()=>[...i[21]||(i[21]=[s("Linux中國",-1)])]),_:1}),i[24]||(i[24]=s(" 榮譽推出",-1))])])}const y=o(u,[["render",g]]);export{v as __pageData,y as default};
